def cmd_extract(args):
    from extraction.merger import merge_project
    merge_project(args.input, args.output, args.name)
    if args.load_neo4j:
        from graph.loader import load
        load(args.output)

def cmd_export(args):
    from export.obsidian import export
    export(args.graph, args.out)

def cmd_query(args):
    from query.engine import QueryEngine
    engine = QueryEngine(args.graph)
    print(f"[*] Loaded graph: {args.graph}")
    print("[*] Type your question. Enter 'exit' to quit.\n")

    history: list[dict] = []
    while True:
        try:
            question = input("> ").strip()
        except (EOFError, KeyboardInterrupt):
            break
        if not question:
            continue
        if question.lower() in ("exit", "quit", "q"):
            break

        answer, sources = engine.ask(question, history)
        if sources:
            print(f"[graph] {', '.join(sources)}")
        print(f"[llm]  {answer}\n")

        history.append({"role": "user", "content": question})
        history.append({"role": "assistant", "content": answer})

def _node_type_to_color(node_type: str) -> str:
    color_map = {
        "File": "#1f77b4",
        "Class": "#2ca02c",
        "Function": "#d62728",
        "Variable": "#bcbd22",
        "Dependency": "#7f7f7f",
    }
    return color_map.get(node_type, "#999999")

def _node_label(node_id: str, data: dict[str, Any]) -> str:
    node_type = data.get("type", "")
    if node_type == "File":
        return os.path.basename(data.get("file_path") or node_id)
    return data.get("name") or node_id.split("::")[-1]

def build_file_level_graph(full_graph: nx.MultiDiGraph) -> nx.MultiDiGraph:
    """Collapse the full graph into a file-to-file overview graph."""
    file_graph = nx.MultiDiGraph()
    file_stats: dict[str, dict[str, Any]] = defaultdict(
        lambda: {"node_count": 0, "function_count": 0, "class_count": 0, "dependency_count": 0}
    )

    for node_id, data in full_graph.nodes(data=True):
        file_path = data.get("file_path")
        if not file_path:
            continue

        stats = file_stats[file_path]
        stats["node_count"] += 1

        node_type = data.get("type")
        if node_type == "Function":
            stats["function_count"] += 1
        elif node_type == "Class":
            stats["class_count"] += 1
        elif node_type == "Dependency":
            stats["dependency_count"] += 1

    for file_path, stats in file_stats.items():
        label = _safe_basename(file_path)
        file_graph.add_node(
            file_path,
            name=label,
            type="File",
            file_path=file_path,
            stats=stats,
            display_title=f"{label}\n({stats['node_count']} nodes)",
            size=3600 + stats["node_count"] * 150,
        )

    edge_weights: dict[tuple[str, str], int] = defaultdict(int)
    for source_id, target_id, edge_data in full_graph.edges(data=True):
        if edge_data.get("relationship") != "CALLS":
            continue

        source_file = full_graph.nodes[source_id].get("file_path")
        target_file = full_graph.nodes[target_id].get("file_path")
        if not source_file or not target_file or source_file == target_file:
            continue

        edge_weights[(source_file, target_file)] += 1

    for (source_file, target_file), weight in edge_weights.items():
        file_graph.add_edge(source_file, target_file, relationship="CALLS", weight=weight)

    return file_graph

def build_file_detail_graph(full_graph: nx.MultiDiGraph, file_path: str, depth: int = 1) -> nx.MultiDiGraph:
    """Build a focused graph for a single file and its immediate relations."""
    detail_graph = nx.MultiDiGraph()

    file_nodes = {
        node_id
        for node_id, data in full_graph.nodes(data=True)
        if data.get("file_path") == file_path
    }

    if not file_nodes:
        return detail_graph

    file_node_id = next(
        (
            node_id
            for node_id, data in full_graph.nodes(data=True)
            if data.get("type") == "File" and data.get("file_path") == file_path
        ),
        None,
    )

    included_nodes = set(file_nodes)
    if file_node_id:
        included_nodes.add(file_node_id)

    frontier = set(file_nodes)
    for _ in range(max(depth, 0)):
        next_frontier = set()
        for node_id in frontier:
            neighbors = set(full_graph.predecessors(node_id)) | set(full_graph.successors(node_id))
            for neighbor in neighbors:
                edge_data_map = full_graph.get_edge_data(node_id, neighbor) or full_graph.get_edge_data(neighbor, node_id) or {}
                relationship_types = {data.get("relationship") for data in edge_data_map.values()}

                if relationship_types & {"CALLS", "CONTAINS", "INHERITS", "IMPORTS", "USES_VARIABLE"}:
                    if neighbor not in included_nodes:
                        next_frontier.add(neighbor)
                    included_nodes.add(neighbor)

        frontier = next_frontier

    for node_id in included_nodes:
        detail_graph.add_node(node_id, **full_graph.nodes[node_id])

    for source_id, target_id, edge_data in full_graph.edges(data=True):
        if source_id in included_nodes and target_id in included_nodes:
            detail_graph.add_edge(source_id, target_id, **edge_data)

    return detail_graph

def toggle_info_panel(self) -> None:
        if self.panel_visible:
            self.container.forget(self.info_frame)
            self.toggle_button.configure(text="Hiện bảng thông tin")
        else:
            self.container.insert(0, self.info_frame, weight=1)
            self.toggle_button.configure(text="Ẩn bảng thông tin")
        self.panel_visible = not self.panel_visible

def _on_canvas_click(self, event: Any) -> None:
        if event.inaxes != self.axis:
            return

        node_id = self._find_node_at_position(event.xdata, event.ydata)
        if not node_id:
            return

        self.current_selection = node_id
        self._update_info_panel(node_id)

        node_data = self.current_view.graph.nodes[node_id]
        if node_data.get("type") == "File" and self.current_view.file_path != node_data.get("file_path"):
            self._drill_into_file(node_data.get("file_path", ""), selected_node_id=node_id)
        else:
            self._render_current_view()

def _find_node_at_position(self, x: float | None, y: float | None) -> str | None:
        if x is None or y is None:
            return None

        best_node_id = None
        best_distance = float("inf")

        for node_id, (nx_pos, ny_pos) in self.node_positions.items():
            distance = ((x - nx_pos) ** 2 + (y - ny_pos) ** 2) ** 0.5
            threshold = 0.08 + (self.node_sizes.get(node_id, 1200) / 12000.0)
            if distance < threshold and distance < best_distance:
                best_node_id = node_id
                best_distance = distance

        return best_node_id

def explain_function(graph: nx.DiGraph, func_name: str) -> str:
    # Build the recursive call chain and format it as a tree
    chain = get_call_chain(graph, func_name, depth=3)
    return format_call_chain(chain)

def export(graph_path: str, vault_path: str) -> None:
    graph = json.loads(Path(graph_path).read_text(encoding="utf-8"))
    project_name = graph["project"]
    nodes = {n["id"]: n for n in graph["nodes"]}

    # Chỉ build adjacency cho edges đã resolved (confidence > 0.0)
    # Edge confidence=0.0 là external lib hoặc ambiguous — tạo wikilink gãy nếu giữ lại
    outgoing: dict[str, list[dict]] = {nid: [] for nid in nodes}
    incoming: dict[str, list[dict]] = {nid: [] for nid in nodes}
    for edge in graph["edges"]:
        if edge["confidence"] > 0.0:
            src, tgt = edge["source_id"], edge["target_id"]
            if src in outgoing and tgt in incoming:
                outgoing[src].append(edge)
                incoming[tgt].append(edge)

    vault_root = Path(vault_path) / _safe(project_name)
    for subdir in ("modules", "classes", "functions"):
        (vault_root / subdir).mkdir(parents=True, exist_ok=True)

    count = 0
    for node_id, node in nodes.items():
        content = _render(node, nodes, outgoing, incoming)
        subdir = {"Module": "modules", "Class": "classes", "Function": "functions"}.get(node["type"], "misc")
        out_file = vault_root / subdir / (_safe(node["name"]) + ".md")
        out_file.write_text(content, encoding="utf-8")
        count += 1

    print(f"[+] Obsidian vault -> {vault_root}")
    print(f"    Files: {count}")

def _render(node, nodes, outgoing, incoming) -> str:
    t = node["type"]
    if t == "Module":
        return _module(node, nodes, outgoing, incoming)
    if t == "Class":
        return _class(node, nodes, outgoing, incoming)
    if t == "Function":
        return _function(node, nodes, outgoing, incoming)
    return ""

def _module(node, nodes, outgoing, incoming) -> str:
    nid = node["id"]
    lines = [f"# {node['name']}", f"**Type:** Module", f"**File:** `{node['file_path']}`", ""]

    imports = _targets(_edges_of(nid, outgoing, "IMPORTS"), nodes)
    if imports:
        lines += ["## Imports"] + [f"- {_wikilink(n)}" for n in imports] + [""]

    defines = _edges_of(nid, outgoing, "DEFINES")
    classes = [nodes[e["target_id"]] for e in defines if e["target_id"] in nodes and nodes[e["target_id"]]["type"] == "Class"]
    funcs   = [nodes[e["target_id"]] for e in defines if e["target_id"] in nodes and nodes[e["target_id"]]["type"] == "Function"]

    if classes:
        lines += ["## Classes"] + [f"- {_wikilink(c)}" for c in classes] + [""]
    if funcs:
        lines += ["## Functions"] + [f"- {_wikilink(f)}" for f in funcs] + [""]

    imported_by = _sources(_edges_of(nid, incoming, "IMPORTS"), nodes)
    if imported_by:
        lines += ["## Imported by"] + [f"- {_wikilink(m)}" for m in imported_by] + [""]

    return "\n".join(lines)

def _class(node, nodes, outgoing, incoming) -> str:
    nid = node["id"]
    lines = [
        f"# {node['name']}",
        f"**Type:** Class",
        f"**File:** `{node['file_path']}`",
        f"**Line:** {node['line_start']}",
        "",
    ]

    if node.get("docstring"):
        lines += ["## Docstring", node["docstring"], ""]

    methods = _targets(_edges_of(nid, outgoing, "CONTAINS"), nodes)
    if methods:
        lines += ["## Methods"] + [f"- {_wikilink(m)}" for m in methods] + [""]

    inherits = _targets(_edges_of(nid, outgoing, "INHERITS"), nodes)
    if inherits:
        lines += ["## Inherits"] + [f"- {_wikilink(b)}" for b in inherits] + [""]

    defined_in = _sources(_edges_of(nid, incoming, "DEFINES"), nodes)
    if defined_in:
        lines += ["## Defined in"] + [f"- {_wikilink(m)}" for m in defined_in] + [""]

    return "\n".join(lines)

def _function(node, nodes, outgoing, incoming) -> str:
    nid = node["id"]
    type_label = "Async Function" if node.get("is_async") else "Function"
    lines = [
        f"# {node['name']}",
        f"**Type:** {type_label}",
        f"**File:** `{node['file_path']}`",
        f"**Line:** {node['line_start']}",
    ]
    if node.get("decorators"):
        lines.append(f"**Decorators:** {', '.join(node['decorators'])}")
    lines.append("")

    if node.get("docstring"):
        lines += ["## Docstring", node["docstring"], ""]

    # Kiểm tra CONTAINS trước DEFINES để method hiện "Class" thay vì "Module"
    for etype, label in (("CONTAINS", "Class"), ("DEFINES", "Module")):
        containers = _sources(_edges_of(nid, incoming, etype), nodes)
        if containers:
            lines += [f"## {label}"] + [f"- {_wikilink(c)}" for c in containers] + [""]
            break

    calls = _targets(_edges_of(nid, outgoing, "CALLS"), nodes)
    if calls:
        lines += ["## Calls"] + [f"- {_wikilink(c)}" for c in calls] + [""]

    callers = _sources(_edges_of(nid, incoming, "CALLS"), nodes)
    if callers:
        lines += ["## Called by"] + [f"- {_wikilink(c)}" for c in callers] + [""]

    return "\n".join(lines)

def visit_Import(self, node: ast.Import):
        for alias in node.names:
            # confidence=0.0 vì chưa biết đây là module nội bộ hay thư viện ngoài
            # resolver sẽ nâng confidence lên 1.0 nếu tìm thấy trong project
            self.edges.append(GraphEdge(
                type=EdgeType.IMPORTS,
                source_id=self.module_id,
                target_id=f"dep:{alias.name}",
                confidence=0.0,
            ))

def visit_ImportFrom(self, node: ast.ImportFrom):
        if node.module:
            self.edges.append(GraphEdge(
                type=EdgeType.IMPORTS,
                source_id=self.module_id,
                target_id=f"dep:{node.module}",
                confidence=0.0,
            ))

def _resolve_name(node: ast.expr) -> Optional[str]:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        parts = []
        cur = node
        while isinstance(cur, ast.Attribute):
            parts.append(cur.attr)
            cur = cur.value
        if isinstance(cur, ast.Name):
            parts.append(cur.id)
            return ".".join(reversed(parts))
    return None

def _collect_calls(func_node) -> List[str]:
    class _Collector(ast.NodeVisitor):
        def __init__(self):
            self.calls: List[str] = []

        def visit_Call(self, node: ast.Call):
            name = _resolve_name(node.func)
            if name:
                self.calls.append(name)
            self.generic_visit(node)

        # Dừng tại nested function — chỉ thu thập call ở body trực tiếp của hàm này
        def visit_FunctionDef(self, node):
            pass

        def visit_AsyncFunctionDef(self, node):
            pass

    collector = _Collector()
    for stmt in func_node.body:
        collector.visit(stmt)
    return collector.calls

def _edge_dict(e: GraphEdge) -> dict:
    return {
        "type": e.type.value,
        "source_id": e.source_id,
        "target_id": e.target_id,
        "confidence": e.confidence,
    }

class ImportResolver:
    """
    Nhận danh sách nodes + edges thô (chứa ghost IDs), trả về edges đã resolve.

    Ghost ID scheme (từ extractor):
      dep:module.name     → cần map về module:path
      class_ref:ClassName → cần map về class:path::Name
      func_ref:func_name  → cần map về func:path::Name (best-effort)

    Edges không resolve được (external lib, builtin) giữ confidence=0.0
    và sẽ bị lọc ra ở export/query layer.
    """

    def __init__(self, project_root: str, nodes: List[GraphNode]):
        self._root = Path(project_root).resolve()
        # Ba map riêng vì mỗi loại ghost ID có chiến lược resolve khác nhau
        self._module_map: Dict[str, str] = {}   # "extraction.extractor" → node_id
        self._class_map: Dict[str, List[str]] = {}  # "ClassName" → [node_ids]
        self._func_map: Dict[str, List[str]] = {}   # "func_name" → [node_ids]
        self._build_maps(nodes)

    def _build_maps(self, nodes: List[GraphNode]):
        for node in nodes:
            if node.type == NodeType.MODULE:
                dotted = self._to_dotted(node.file_path)
                if dotted:
                    self._module_map[dotted] = node.id
            elif node.type == NodeType.CLASS:
                self._class_map.setdefault(node.name, []).append(node.id)
            elif node.type == NodeType.FUNCTION:
                self._func_map.setdefault(node.name, []).append(node.id)

    def _to_dotted(self, file_path: str) -> Optional[str]:
        # "C:/project/extraction/extractor.py" → "extraction.extractor"
        try:
            rel = Path(file_path).resolve().relative_to(self._root)
            return rel.with_suffix("").as_posix().replace("/", ".")
        except ValueError:
            return None  # file nằm ngoài project root — bỏ qua

    def resolve(self, edges: List[GraphEdge]) -> List[GraphEdge]:
        return [self._resolve_one(e) for e in edges]

    def _resolve_one(self, edge: GraphEdge) -> GraphEdge:
        tgt = edge.target_id

        if tgt.startswith("dep:"):
            resolved = self._resolve_module(tgt[4:])
            return self._make(edge, resolved, conf_hit=1.0)

        if tgt.startswith("class_ref:"):
            resolved = self._resolve_class(tgt[10:])
            return self._make(edge, resolved, conf_hit=1.0)

        if tgt.startswith("func_ref:"):
            resolved, conf = self._resolve_func(tgt[9:], edge.source_id)
            return self._make(edge, resolved, conf_hit=conf)

        return edge  # edge đã resolve sẵn (DEFINES, CONTAINS) — giữ nguyên

    def _make(self, edge: GraphEdge, resolved: Optional[str], conf_hit: float) -> GraphEdge:
        if resolved:
            return GraphEdge(
                type=edge.type,
                source_id=edge.source_id,
                target_id=resolved,
                confidence=conf_hit,
            )
        # Không tìm thấy → giữ ghost ID, đánh confidence=0.0 để filter ra sau
        return GraphEdge(
            type=edge.type,
            source_id=edge.source_id,
            target_id=edge.target_id,
            confidence=0.0,
        )

    def _resolve_module(self, module_name: str) -> Optional[str]:
        if module_name in self._module_map:
            return self._module_map[module_name]
        # "from extraction.extractor import X" → module_name = "extraction.extractor"
        # cũng khớp nếu chỉ import package cha "from extraction import ..."
        for key, val in self._module_map.items():
            if key == module_name or key.startswith(module_name + "."):
                return val
        return None  # thư viện ngoài (ast, os, typing…) — drop

    def _resolve_class(self, class_name: str) -> Optional[str]:
        # Dùng phần cuối: "ast.NodeVisitor" → "NodeVisitor" để bỏ qua tiền tố module
        short = class_name.split(".")[-1]
        candidates = self._class_map.get(short, [])
        return candidates[0] if candidates else None

    def _resolve_func(self, func_ref: str, caller_id: str) -> tuple[Optional[str], float]:
        short = func_ref.split(".")[-1]
        candidates = self._func_map.get(short, [])
        if not candidates:
            return None, 0.0
        if len(candidates) == 1:
            # Chỉ một hàm có tên này trong project → khá chắc
            return candidates[0], 0.7
        # Nhiều hàm cùng tên → ưu tiên file giống caller để giảm false positive
        caller_file = caller_id.split("::")[0]
        for prefix in ("func:", "module:", "class:"):
            caller_file = caller_file.replace(prefix, "")
        same_file = [c for c in candidates if caller_file in c]
        return (same_file[0] if same_file else candidates[0]), 0.5

def _build_maps(self, nodes: List[GraphNode]):
        for node in nodes:
            if node.type == NodeType.MODULE:
                dotted = self._to_dotted(node.file_path)
                if dotted:
                    self._module_map[dotted] = node.id
            elif node.type == NodeType.CLASS:
                self._class_map.setdefault(node.name, []).append(node.id)
            elif node.type == NodeType.FUNCTION:
                self._func_map.setdefault(node.name, []).append(node.id)

def _to_dotted(self, file_path: str) -> Optional[str]:
        # "C:/project/extraction/extractor.py" → "extraction.extractor"
        try:
            rel = Path(file_path).resolve().relative_to(self._root)
            return rel.with_suffix("").as_posix().replace("/", ".")
        except ValueError:
            return None

def _resolve_one(self, edge: GraphEdge) -> GraphEdge:
        tgt = edge.target_id

        if tgt.startswith("dep:"):
            resolved = self._resolve_module(tgt[4:])
            return self._make(edge, resolved, conf_hit=1.0)

        if tgt.startswith("class_ref:"):
            resolved = self._resolve_class(tgt[10:])
            return self._make(edge, resolved, conf_hit=1.0)

        if tgt.startswith("func_ref:"):
            resolved, conf = self._resolve_func(tgt[9:], edge.source_id)
            return self._make(edge, resolved, conf_hit=conf)

        return edge

def _make(self, edge: GraphEdge, resolved: Optional[str], conf_hit: float) -> GraphEdge:
        if resolved:
            return GraphEdge(
                type=edge.type,
                source_id=edge.source_id,
                target_id=resolved,
                confidence=conf_hit,
